def copy_and_convert_image(source_path, dest_path):
    """
    Copies an image from source to destination, converting to JPEG if needed.
    Returns True if successful, False otherwise.
    """
    try:
        if os.path.exists(source_path):
            os.makedirs(os.path.dirname(dest_path), exist_ok=True)

            # Check if conversion is needed
            source_ext = os.path.splitext(source_path)[1].lower()
            if source_ext in ['.jpg', '.jpeg']:
                # Just copy
                shutil.copy2(source_path, dest_path)
            else:
                # Convert to JPEG using Pillow
                with Image.open(source_path) as img:
                    # Convert to RGB if necessary (for PNG with transparency, etc.)
                    if img.mode in ('RGBA', 'P'):
                        img = img.convert('RGB')
                    img.save(dest_path, 'JPEG', quality=90)
            return True
    except Exception as e:
        print(f"Failed to copy/convert image from {source_path}: {e}")
    return False


def find_image_file(directory, base_name):
    """
    Finds an image file in directory matching base_name with any extension.
    Returns the full path if found, None otherwise.
    """
    if not os.path.exists(directory):
        return None

    extensions = ['.jpg', '.jpeg', '.png', '.webp', '.avif']
    for ext in extensions:
        path = os.path.join(directory, base_name + ext)
        if os.path.exists(path):
            return path

    # Also check files that start with base_name
    try:
        for filename in os.listdir(directory):
            name_lower = filename.lower()
            if name_lower.startswith(base_name.lower()):
                return os.path.join(directory, filename)
    except:
        pass

    return None


