def reverse_seed(apps, schema_editor):
    """
    Reverse migration - removes all seeded data.
    Deletes in reverse order to respect foreign key constraints.
    """
    PlanEntry = apps.get_model('planner', 'PlanEntry')
    OutfitGarment = apps.get_model('outfits', 'OutfitGarment')
    Outfit = apps.get_model('outfits', 'Outfit')
    Garment = apps.get_model('wardrobe', 'Garment')
    Brand = apps.get_model('wardrobe', 'Brand')

    # Delete in reverse order of creation
    PlanEntry.objects.all().delete()
    OutfitGarment.objects.all().delete()
    Outfit.objects.all().delete()
    Garment.objects.all().delete()
    Brand.objects.all().delete()


class Migration(migrations.Migration):
    """
    Data Migration: Comprehensive Sample Data Seeding

    This migration populates the database with realistic sample data for:
    - 10 Brands (with name, website, country)
    - 35 Garments (all categories: tops, bottoms, outerwear, footwear, accessories)
    - 8 Outfits (various occasions and seasons)
    - Outfit-Garment relationships (many-to-many through model)
    - 14 Plan Entries (next two weeks of planned outfits)

    Usage:
        python manage.py migrate

    To reverse:
        python manage.py migrate wardrobe 0006
    """

    dependencies = [
        ('wardrobe', '0006_alter_garment_category_alter_garment_image_and_more'),
        ('outfits', '0007_alter_outfitgarment_options_and_more'),
        ('planner', '0004_alter_planentry_options'),
    ]

    operations = [
        migrations.RunPython(seed_all_data, reverse_seed),
    ]
